-- Agronomy: soil samples, site data of fields for the fertilizer need calculation (DüV §4),
-- the records of those calculations, and the states' Nmin reference values.

-- ---------------------------------------------------------------------------
-- Site data
-- ---------------------------------------------------------------------------

ALTER TABLE fields
  -- Nitrate-polluted or eutrophic area (rotes / gelbes Gebiet, DüV §13a): N need −20 %, longer closed periods.
  ADD COLUMN nitrate_sensitive_zone boolean NOT NULL DEFAULT false,
  ADD COLUMN phosphate_sensitive_zone boolean NOT NULL DEFAULT false,
  -- Soil texture class (Bodenart) as used by the LUFA / VDLUFA tables.
  ADD COLUMN soil_texture text CHECK (soil_texture IN ('S', 'lS', 'sU', 'ssL', 'lU', 'sL', 'uL', 'L', 'utL', 'tL', 'T'));

-- Federal state of a farm: decides the Nmin reference values and the authority export format.
ALTER TABLE farms
  ADD COLUMN federal_state text CHECK (federal_state IN ('BW', 'BY', 'BE', 'BB', 'HB', 'HH', 'HE', 'MV', 'NI', 'NW', 'RP', 'SL', 'SN', 'ST', 'SH', 'TH'));

ALTER TABLE crop_cycles
  -- Straw or other by-products removed from the field: raises the P/K/Mg removal.
  ADD COLUMN straw_removed boolean NOT NULL DEFAULT false,
  -- Covered with film or fleece: +20 kg N/ha in the N need (DüV Anlage 4).
  ADD COLUMN film_or_fleece boolean NOT NULL DEFAULT false,
  -- Crude protein of the harvest in % of dry matter (grassland and field forage).
  ADD COLUMN protein_pct numeric(5, 2) CHECK (protein_pct BETWEEN 0 AND 60);

-- ---------------------------------------------------------------------------
-- Soil samples
-- ---------------------------------------------------------------------------

-- A basic soil analysis (pH, P, K, Mg, humus; every few years) or a spring Nmin sample by layer.
CREATE TABLE soil_samples (
  id               uuid PRIMARY KEY DEFAULT uuidv7(),
  organization_id  uuid NOT NULL,
  field_id         uuid NOT NULL,
  field_part_id    uuid,
  kind             text NOT NULL CHECK (kind IN ('basic', 'nmin')),
  sampled_on       date NOT NULL,
  lab              text,
  sample_number    text,
  depth_cm         smallint CHECK (depth_cm BETWEEN 1 AND 200),
  ph               numeric(4, 2) CHECK (ph BETWEEN 2 AND 11),
  ph_method        text CHECK (ph_method IN ('cacl2', 'h2o', 'kcl')),
  -- mg per 100 g soil; P and K extracted with CAL (or DL), Mg with CaCl2.
  p2o5_mg_100g     numeric(7, 2) CHECK (p2o5_mg_100g >= 0),
  p_method         text CHECK (p_method IN ('cal', 'dl')),
  k2o_mg_100g      numeric(7, 2) CHECK (k2o_mg_100g >= 0),
  mgo_mg_100g      numeric(7, 2) CHECK (mgo_mg_100g >= 0),
  humus_pct        numeric(5, 2) CHECK (humus_pct BETWEEN 0 AND 100),
  soil_texture     text CHECK (soil_texture IN ('S', 'lS', 'sU', 'ssL', 'lU', 'sL', 'uL', 'L', 'utL', 'tL', 'T')),
  -- Mineral N (NO3-N + NH4-N) in kg N/ha by layer.
  nmin_0_30        numeric(6, 1) CHECK (nmin_0_30 >= 0),
  nmin_30_60       numeric(6, 1) CHECK (nmin_30_60 >= 0),
  nmin_60_90       numeric(6, 1) CHECK (nmin_60_90 >= 0),
  notes            text,
  created_by       uuid REFERENCES users(id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  FOREIGN KEY (organization_id, field_id) REFERENCES fields (organization_id, id) ON DELETE CASCADE,
  FOREIGN KEY (organization_id, field_id, field_part_id) REFERENCES field_parts (organization_id, field_id, id) ON DELETE SET NULL (field_part_id),
  CHECK (kind <> 'nmin' OR coalesce(nmin_0_30, nmin_30_60, nmin_60_90) IS NOT NULL)
);
CREATE INDEX soil_samples_field_idx ON soil_samples (organization_id, field_id, kind, sampled_on DESC);

-- ---------------------------------------------------------------------------
-- Fertilizer need records (DüV §3 Abs. 2: the calculation is to be documented)
-- ---------------------------------------------------------------------------

-- Append-only: each saved calculation keeps its inputs, result and rule set.
CREATE TABLE fertilizer_need_records (
  id               uuid PRIMARY KEY DEFAULT uuidv7(),
  organization_id  uuid NOT NULL,
  crop_cycle_id    uuid NOT NULL,
  kind             text NOT NULL CHECK (kind IN ('n', 'pk')),
  inputs           jsonb NOT NULL,
  result           jsonb NOT NULL,
  ruleset          text NOT NULL,
  created_by       uuid REFERENCES users(id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, crop_cycle_id) REFERENCES crop_cycles (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX fertilizer_need_records_cycle_idx ON fertilizer_need_records (crop_cycle_id, kind, created_at DESC);

-- ---------------------------------------------------------------------------
-- Nmin reference values (shared reference data)
-- ---------------------------------------------------------------------------

-- Spring Nmin reference values the federal states publish for the fertilizer need calculation, as
-- each state words them (region, crop, previous crop, soil). Ported from AGVOLUTION/agmeo
-- (scripts/generate-nmin-reference.py). They are offered to the user, never picked automatically.
CREATE TABLE nmin_reference_values (
  id             uuid PRIMARY KEY DEFAULT uuidv7(),
  state          text NOT NULL,
  region         text,
  crop           text NOT NULL,
  previous_crop  text,
  soil           text,
  n0_30          numeric(6, 1),
  n30_60         numeric(6, 1),
  n60_90         numeric(6, 1),
  -- kg N/ha over `depth`.
  total          numeric(6, 1) NOT NULL,
  depth          text NOT NULL DEFAULT '0-90',
  samples        integer,
  week           smallint,
  year           smallint NOT NULL,
  source         text NOT NULL
);
CREATE INDEX nmin_reference_values_state_idx ON nmin_reference_values (state, year);


ALTER TABLE soil_samples ENABLE ROW LEVEL SECURITY;
ALTER TABLE fertilizer_need_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY soil_samples_tenant ON soil_samples FOR ALL
  USING (organization_id = (SELECT app.org_id())) WITH CHECK (organization_id = (SELECT app.org_id()));
CREATE POLICY fertilizer_need_records_tenant ON fertilizer_need_records FOR ALL
  USING (organization_id = (SELECT app.org_id())) WITH CHECK (organization_id = (SELECT app.org_id()));
GRANT SELECT, INSERT, UPDATE, DELETE ON soil_samples TO agmeo_app;
GRANT SELECT, INSERT ON fertilizer_need_records TO agmeo_app;
GRANT SELECT ON nmin_reference_values TO agmeo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON nmin_reference_values TO agmeo_refdata;
